COOKIE_KEY_SETTING_MORE_READ = "settings_more_read_v3";
const defaultSettings = {
    fontSize: 18,
    fontFamily: "default",
    theme: "dark",
    bgcolor: "black",
    hgcolor: "purple",
    lang: "en",
    ttsvoice: 0,
    ttsrate: 1,
    lineHeight: '1.6',
    textAlign: 'left',
    pageWidth: '100%',
    paragraphHeigh: '20px',
    autoNext: false,
    autoScroll: false,
    scrollSpeed: 5,
    textIndent: false,
    bionicReading: false,
    copyText: true
};
function getSettings() {
    const saved = Cookies.get(COOKIE_KEY_SETTING_MORE_READ);
    return saved ? JSON.parse(saved) : { ...defaultSettings };
}
function saveSettings(settings) {
    Cookies.set(COOKIE_KEY_SETTING_MORE_READ, JSON.stringify(settings), {
        expires: 365,
        secure: true
    });
}
function applyDarkMode(theme) {
    const settings = getSettings();
    const btn = $('.nightmode_switch');
    if (theme == 'dark') {
        $(".action-select a[data-tool='night'] i").removeClass("icon-moon").addClass("icon-sun");
        btn.find("i").removeClass("icon-moon").addClass("icon-sun");
        btn.attr("data-content", "Light Theme");
        $("html").attr("theme", theme).attr("bgcolor", settings.bgcolor).attr("hgcolor", settings.hgcolor);
    } else {
        $(".action-select a[data-tool='night'] i").removeClass("icon-sun").addClass("icon-moon");
        btn.find("i").removeClass("icon-sun").addClass("icon-moon");
        btn.attr("data-content", "Dark Theme");
        $("html").attr("theme", theme).attr("bgcolor", "white").attr("hgcolor", settings.hgcolor);
    }
}
$(document).on("click", ".nightmode_switch", function(e) {
    var theme = document.documentElement.getAttribute("theme");
    if (theme == 'dark') {
        theme = 'light';
    } else {
        theme = 'dark';
    }
    const settings = getSettings();
    settings['theme'] = theme;
    saveSettings(settings);
    applyDarkMode(theme);
})
